import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [symbol, setSymbol] = useState('BBRI');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

    const fetchStock = async () => {
        setLoading(true);
      setError(null);
        try {
            const res = await axios.get("http://localhost:5000/stock", {
                params: { symbol }
            });

        if (res.data && Array.isArray(res.data.data)) {
                setStockData(res.data.data);
            } else {
          setError('Invalid data format received from server');
          setStockData([]);
            }
        } catch (err) {
            console.error('Error details:', err);
        setStockData([]);

            if (err.response) {
                if (err.response.status === 404) {
            setError(`No data found for symbol: ${symbol}`);
                } else {
            setError(`Server error: ${err.response.data?.error || 'Unknown error'}`);
                }
            } else if (err.request) {
          setError('Server not responding. Please check if backend is running.');
            } else {
          setError(`Failed to fetch data: ${err.message}`);
            }
        } finally {
            setLoading(false);
        }
    };

useEffect(() => {
  fetchStock();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

return (
    <div style={{ padding: '2rem' }}>
      <h1>Stock Data Viewer</h1>
    <div style={{ margin: '1rem 0', display: 'flex', gap: '10px', alignItems: 'center' }}>
      <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value)}
        placeholder="Enter stock symbol (e.g., BBCA.JK)"
        style={{ padding: '8px' }}
      />
      <button
        onClick={fetchStock}
        style={{ padding: '8px 16px', cursor: 'pointer' }}
        disabled={loading}
      >
        {loading ? 'Loading...' : 'Fetch Data'}
      </button>
    </div>

    {error && <div style={{ color: 'red', margin: '1rem 0' }}>{error}</div>}

      {loading ? (
      <p>Loading data...</p>
    ) : stockData.length > 0 ? (
      <table border="1" cellPadding="5" style={{ marginTop: '1rem', borderCollapse: 'collapse' }}>
        <thead style={{ backgroundColor: '#f2f2f2' }}>
            <tr>
            <th>Date</th>
              <th>Open</th>
              <th>High</th>
              <th>Low</th>
              <th>Close</th>
              <th>Volume</th>
            </tr>
            </thead>
            <tbody>
            {stockData.map((row, i) => (
                <tr key={i}>
              <td>{row.Date || row.Datetime}</td>
              <td>{typeof row.Open === 'number' ? row.Open.toFixed(2) : row.Open}</td>
              <td>{typeof row.High === 'number' ? row.High.toFixed(2) : row.High}</td>
              <td>{typeof row.Low === 'number' ? row.Low.toFixed(2) : row.Low}</td>
              <td>{typeof row.Close === 'number' ? row.Close.toFixed(2) : row.Close}</td>
                  <td>{row.Volume}</td>
                </tr>
            ))}
            </tbody>
          </table>
    ) : !error && (
      <p>No data available. Please enter a valid stock symbol and fetch data.</p>
      )}
    </div>
);
}

export default App;
